using Astrea.GameStates;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic", menuName = "Data/Battle/Logics/Dice Action/Default")]
public class DiceActionLogic : ScriptableObject
{
	[Header("Assets")]
	[SerializeField]
	protected GameState actionGameState;

	public GameState ActionGameState => actionGameState;

	public virtual void ActionGrabbed()
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(actionGameState);
	}
}
